import meta from "./generated/meta.json";
import sheet from "./generated/sheet.json";

/**
 * Where the content comes from (generated by scripts/build-data.mjs at build time).
 * Demo data is shown only while the Google Sheet has no published restaurants
 * (AKLA_SHOW_DEMO=auto, the default). Use "always" or "never" to override.
 */
export const DATA_META = meta as {
  generatedAt: string;
  showDemo: "auto" | "always" | "never";
  osm?: { count: number; fetchedAt: string | null; osmBase?: string | null };
  sheet?: { source: string; fetchedAt: string; restaurants: number; meals: number; offers: number; problems?: number; error?: string };
};

export const SHEET = sheet as { restaurants: Record<string, unknown>[]; meals: Record<string, unknown>[]; offers: Record<string, unknown>[] };

export const SHOW_DEMO = DATA_META.showDemo === "always" || (DATA_META.showDemo === "auto" && SHEET.restaurants.length === 0);

export const GENERATED_AT = new Date(DATA_META.generatedAt);
